namespace vP4_3
{

class FunctionSpace: public dolfin::FunctionSpace
{
public:

  // Constructor for standard function space
  FunctionSpace(std::shared_ptr<const dolfin::Mesh> mesh):
    dolfin::FunctionSpace(mesh,
                          std::make_shared<const dolfin::FiniteElement>(std::make_shared<vp4_3_finite_element_1>()),
                          std::make_shared<const dolfin::DofMap>(std::make_shared<vp4_3_dofmap_1>(), *mesh))
  {
    // Do nothing
  }

  // Constructor for constrained function space
  FunctionSpace(std::shared_ptr<const dolfin::Mesh> mesh, std::shared_ptr<const dolfin::SubDomain> constrained_domain):
    dolfin::FunctionSpace(mesh,
                          std::make_shared<const dolfin::FiniteElement>(std::make_shared<vp4_3_finite_element_1>()),
                          std::make_shared<const dolfin::DofMap>(std::make_shared<vp4_3_dofmap_1>(), *mesh, constrained_domain))
  {
    // Do nothing
  }

};

}

